const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const res = JSON.parse(await fs.readFile(S+"\\_GIG50_RESULT.json","utf8"));

// 按「散活类型」分类
const TYPE = {
  "项目接单": ["peopleperhour","freelancer","fl.ru","epwk","codeur","useme","twine","workana","freelance.nl","free-work","twagofreelance","freelancede","beingguru","catalant","kolabtree","worksome","solidgigs","giggrabbers","gigster","toptal","guru","sribu","fastwork","freelancehunt","freelancing.my","coconala","crowdworks","lancers","projectawesome","commissioncrowd","freelanceboard"],
  "赏金悬赏": ["bugcrowd","hackerone","intigriti","huntr","algora","internetbugbounty"],
  "AI训练标注": ["mercor","alignerr","outlier","dataannotation","tasklet"],
  "本地散活": ["taskrabbit"],
  "IT项目": ["justjoin","nofluffjobs","devopsprojectshq","comet","hays"],
  "Web3/加密": ["cryptotask","web3career","cryptojobslist"],
  "远程职位板": ["remoteok","himalayas","remotive","weworkremotely","nodesk","jobicy","jobgether","jobboardsearch"],
};
const map = {};
for (const [t, hosts] of Object.entries(TYPE)) for (const h of hosts) map[h]=t;

const categorize = (o) => {
  const h = String(o.host).replace(/^www\./,"").toLowerCase();
  for (const [t, hosts] of Object.entries(TYPE)) if (hosts.some(x=>h.includes(x))) return t;
  return "其他招聘板";
};

const alive = res.filter(o=>String(o.status).includes("✅"));
const byType = {};
for (const o of alive) { const t=categorize(o); (byType[t] ??= []).push(o); }

const summary = Object.entries(byType).map(([t,arr])=>({
  type: t,
  count: arr.length,
  list: arr.map(o=>o.host).slice(0,40)
}));

return { aliveTotal: alive.length, byType: summary };
